<script setup>
import { computed, inject, onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import { request } from '../services/api';

const config = inject('mobileConfig'); const route = useRoute(); const order = ref(null); const loading = ref(true); const error = ref(''); const taxOpen = ref(false);
const tax = reactive({ taxpayer_name: '', taxpayer_number: '', taxpayer_address: '', taxpayer_email: '', customer_note: '', save_profile: true });
const formatPrice = (value) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0);
const hasTracking = computed(() => order.value?.tracking?.events?.length);
const load = async () => { loading.value = true; try { order.value = (await request(`${config.apiBase}/orders/${encodeURIComponent(route.params.orderId)}`)).data; } catch (exception) { error.value = exception.message; } finally { loading.value = false; } };
const complete = async () => { try { order.value = (await request(`${config.apiBase}/orders/${encodeURIComponent(route.params.orderId)}/complete`, { method: 'POST', body: {} })).data; } catch (exception) { error.value = Object.values(exception.errors || {})[0]?.[0] || exception.message; } };
const cancel = async () => { if (!window.confirm('Batalkan pesanan ini?')) return; try { await request(`${config.apiBase}/orders/${encodeURIComponent(route.params.orderId)}/cancel`, { method: 'POST', body: { cancel_reason: 'Dibatalkan customer dari aplikasi mobile.' } }); await load(); } catch (exception) { error.value = Object.values(exception.errors || {})[0]?.[0] || exception.message; } };
const requestTax = async () => { try { order.value.tax_invoice = (await request(`${config.apiBase}/orders/${encodeURIComponent(route.params.orderId)}/tax-invoice`, { method: 'POST', body: tax })).data; taxOpen.value = false; } catch (exception) { error.value = Object.values(exception.errors || {})[0]?.[0] || exception.message; } };
onMounted(load);
</script>
<template><section class="mobile-screen" aria-labelledby="mobile-route-heading"><RouterLink :to="{ name: 'orders' }" class="mobile-back-link">← Transaksi</RouterLink><span class="mobile-eyebrow">{{ order?.invoice_no }}</span><h1 id="mobile-route-heading" tabindex="-1">Detail Pesanan</h1>
    <p v-if="error" class="mobile-alert">{{ error }}</p><div v-if="loading" class="mobile-skeleton-list"><span v-for="item in 4" :key="item"></span></div>
    <template v-else-if="order"><section class="mobile-checkout-card"><span class="mobile-payment-status">{{ order.status }}</span><h2>{{ order.company }}</h2><strong class="mobile-payment-total">{{ formatPrice(order.grand_total) }}</strong><div class="mobile-order-actions"><RouterLink v-if="order.actions.can_pay" :to="{ name: 'payment', params: { orderId: order.order_id } }" class="mobile-primary-button mobile-button-link">Lanjutkan Pembayaran</RouterLink><button v-if="order.actions.can_complete" class="mobile-primary-button" @click="complete">Pesanan Diterima</button><button v-if="order.actions.can_cancel" class="mobile-clear-button" @click="cancel">Batalkan Pesanan</button><a :href="order.invoice_url" target="_blank" rel="noopener" class="mobile-secondary-button mobile-button-link">Lihat Invoice</a></div></section>
        <section class="mobile-checkout-card"><h2>Produk</h2><div v-for="item in order.items" :key="item.id" class="mobile-checkout-line"><span>{{ item.name }} <small>{{ item.variant }}</small> × {{ item.quantity }}</span><strong>{{ formatPrice(item.subtotal) }}</strong></div><div class="mobile-checkout-line"><span>Subtotal</span><strong>{{ formatPrice(order.subtotal) }}</strong></div><div class="mobile-checkout-line"><span>Pengiriman</span><strong>{{ formatPrice(order.shipping_cost) }}</strong></div><div v-if="order.tax_amount" class="mobile-checkout-line"><span>{{ order.tax_name }}</span><strong>{{ formatPrice(order.tax_amount) }}</strong></div></section>
        <section class="mobile-checkout-card"><h2>Pengiriman</h2><strong>{{ order.shipping.recipient_name }}</strong><span>{{ order.shipping.phone }}</span><p>{{ order.shipping.address }}, {{ order.shipping.district }}, {{ order.shipping.city }}, {{ order.shipping.province }} {{ order.shipping.postal_code }}</p><p v-if="order.shipping.tracking_number"><strong>{{ order.shipping.courier }}</strong> · {{ order.shipping.tracking_number }}</p><p v-if="order.tracking?.message" class="mobile-muted">{{ order.tracking.message }}</p><ol v-if="hasTracking" class="mobile-timeline"><li v-for="event in order.tracking.events" :key="`${event.date}-${event.time}-${event.code}`"><strong>{{ event.description }}</strong><span>{{ event.date }} {{ event.time }} · {{ event.city }}</span></li></ol></section>
        <section class="mobile-checkout-card"><h2>Riwayat status</h2><ol class="mobile-timeline"><li v-for="event in order.timeline" :key="`${event.created_at}-${event.status}`"><strong>{{ event.status }}</strong><span>{{ event.note }}</span></li></ol></section>
        <section class="mobile-checkout-card"><h2>Faktur Pajak</h2><template v-if="order.tax_invoice"><p>Status: <strong>{{ order.tax_invoice.status }}</strong></p><p>{{ order.tax_invoice.taxpayer_name }} · {{ order.tax_invoice.taxpayer_number }}</p><a v-if="order.tax_invoice.download_url" :href="order.tax_invoice.download_url" class="mobile-secondary-button mobile-button-link">Unduh Faktur Pajak</a></template><button v-else-if="order.actions.can_request_tax_invoice" class="mobile-secondary-button" @click="taxOpen = !taxOpen">Minta Faktur Pajak</button>
            <form v-if="taxOpen" class="mobile-account-form" @submit.prevent="requestTax"><label>Nama wajib pajak<input v-model="tax.taxpayer_name" required /></label><label>NPWP<input v-model="tax.taxpayer_number" required inputmode="numeric" /></label><label>Alamat wajib pajak<textarea v-model="tax.taxpayer_address" required></textarea></label><label>Email<input v-model="tax.taxpayer_email" type="email" required /></label><button class="mobile-primary-button">Kirim Permintaan</button></form>
        </section>
    </template>
</section></template>
